#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define ITERATIONS 500000000

// Function executed by the worker thread
void *cancellable_task(void *arg) {
    long i = 0;

    // Ensure cancellation is enabled (Deferred cancellation is the default type)
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
    printf("Worker thread running...\n");

    // Simulate intense computation where standard I/O functions are not used
    while (i < ITERATIONS) {
        i++;

        // Periodically insert a manual cancellation check
        if (i % 50000000 == 0) {
            printf("Worker: Checking cancellation point (i=%ld).\n", i);
            // If a cancellation request is pending, the thread terminates here.
            pthread_testcancel(); 
        }
    }

    printf("Worker thread finished calculation normally (i.e., cancellation failed).\n");
    return (void*)1; // Return 1 if completed normally
}

int main() {
    pthread_t thread;
    void *res;

    if (pthread_create(&thread, NULL, cancellable_task, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    // Wait briefly (2 seconds) before sending the cancellation request
    sleep(2);

    printf("Main: Requesting cancellation of worker thread.\n");
    if (pthread_cancel(thread) != 0) {
        perror("pthread_cancel");
        return 1;
    }

    // Wait for the worker thread to terminate
    if (pthread_join(thread, &res) != 0) {
        perror("pthread_join");
        return 1;
    }

    // Check the exit status of the terminated thread
    if (res == PTHREAD_CANCELED) {
        printf("Main: Worker thread terminated successfully via cancellation point.\n");
    } else {
        printf("Main: Worker thread finished normally (Result: %p).\n", res);
    }

    return 0;
}
